def fill_between(g, marker, axis, fill_any=False):
    o=g.copy(); H,W=g.shape
    if axis=='col':
        for c in range(W):
            m=np.where(g[:,c]==marker)[0]
            if len(m)>=2:
                for r in range(m[0]+1,m[-1]):
                    if fill_any or g[r,c]!=marker:
                        o[r,c]=3
    else:
        for r in range(H):
            m=np.where(g[r]==marker)[0]
            if len(m)>=2:
                for c in range(m[0]+1,m[-1]):
                    if fill_any or g[r,c]!=marker:
                        o[r,c]=3
    return o

for axis in ['col','row']:
