def zero_runs_bounded(g, marker, axis):
    o=g.copy(); H,W=g.shape
    if axis=='col':
        for c in range(W):
            col=g[:,c]; r=0
            while r<H:
                if col[r]==0:
                    s=r
                    while r<H and col[r]==0: r+=1
                    e=r-1
                    if s>0 and e<H-1 and col[s-1]==marker and col[e+1]==marker:
                        o[s:e+1,c]=3
                else: r+=1
    else:
        for r in range(H):
            row=g[r]; c=0
            while c<W:
                if row[c]==0:
                    s=c
                    while c<W and row[c]==0: c+=1
                    e=c-1
                    if s>0 and e<W-1 and row[s-1]==marker and row[e+1]==marker:
                        o[r,s:e+1]=3
                else: c+=1
    return o
